/** Hero -- generated by the template lab from Figma node 538:41041
 *  (Hero). Everything is drawn from the board itself
 *  (FigmaLayers); the slots below are what a designer edits, each in its
 *  board place and stacking order:
 *    copy tied to the brief -- cta/shop-now, lead, amount;
 *    board copy, editable -- text, off, hike, camp, climb, more;
 *    photos -- photo; brand slots -- none.
 *  Text contracts come from each board layer (boardFit). NUDGE (./nudges.ts)
 *  holds the fix loop's per-layer corrections to Figma's render. */
import type { SheetAsset } from '../../../../../sheet/types';
import { Ground } from '../../../../../edit/Editable';
import { Picture } from '../../../../../edit/Picture';
import { ZONE_LIST, photoFor } from '../../../../../model/compose';
import { FigmaLayers, FigmaText, FigmaMark, type Slot } from '../../../../../render/figma/FigmaLayers';
import { cropOf, type FigmaLayout } from '../../../../../render/figma/layout';
import board from './layout.json';
import { NUDGE } from './nudges';

/** Which board layer each editable layer is, by the part of its id after the asset's. */
export const HERO_538_41041_FIGMA = {
  "cta/shop-now": "538:41043", // cta: Shop Now
  "lead": "538:41045", // lead: UP TO
  "amount": "538:41046", // amount: 60
  "text": "538:41047", // text: %
  "off": "538:41048", // text: OFF
  "hike": "538:41057", // text: HIKE
  "camp": "538:41061", // text: CAMP
  "climb": "538:41067", // text: CLIMB
  "more": "538:41071", // text: & MORE
  "cta/cta": "538:41042", // pill: CTA
  "art/subtract": "538:41050", // graphic: Subtract
} as const;

export function Hero_538_41041({ asset }: { asset: SheetAsset }) {
  const layout = board as unknown as FigmaLayout, id = asset.id;
  const zone = ZONE_LIST.find(z => z.id === asset.media.photo) ?? photoFor('hike', 0);
  const slots: Record<string, Slot> = {
    [HERO_538_41041_FIGMA["cta/shop-now"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/cta/shop-now`} contract="lab.cta" layout={layout}
      text={asset.copy.cta || l.text!.chars} />,
    [HERO_538_41041_FIGMA["lead"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/lead`} contract="lab.lead" layout={layout}
      text={asset.copy.lead ? (l.text!.chars.includes('\u2028') ? asset.copy.lead.replace(/\s+/, '\n') : asset.copy.lead) : l.text!.chars} />,
    [HERO_538_41041_FIGMA["amount"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/amount`} contract="lab.amount" layout={layout}
      text={l.text!.chars.replace(/\d+/, (asset.copy.offer ?? '').match(/(\d+)\s*%/)?.[1] ?? (asset.copy.offer ?? '').match(/\d+/)?.[0] ?? '$&')} />,
    [HERO_538_41041_FIGMA["text"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/text`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_41041_FIGMA["off"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/off`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_41041_FIGMA["hike"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/hike`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_41041_FIGMA["camp"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/camp`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_41041_FIGMA["climb"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/climb`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_41041_FIGMA["more"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/more`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_41041_FIGMA["cta/cta"]]: (l, box, _n, board) => <>
      <FigmaMark l={l} box={box} id={`${id}/cta/cta/mark`} src="/graphics/named-sale-pill-470x120-16vaikd.svg" fill="#79AC42" layout={layout} />
      {board({ bare: true })}
    </>,
    [HERO_538_41041_FIGMA["art/subtract"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/art/subtract/mark`} src="/graphics/named-sale-subtract-17n13m4.svg"
      fill="#79AC42" layout={layout} />,
  };
  const [w, h] = layout.size;
  // The frame's own photo, swappable, under every layer (and not drawn again by FigmaLayers).
  const photo = layout.frame.images?.[0] && layout.assets?.[layout.frame.images[0].ref];
  const crop = photo && layout.frame.crop ? cropOf(layout.frame.crop, [w, h], [photo.w, photo.h]) : undefined;
  const drawn = { ...layout, frame: { ...layout.frame, paints: layout.frame.paints?.filter(p => p.type !== 'IMAGE') } };
  // data-figma-compiled: the studio's Figma export reads a compiled board's way (toLayers).
  return <Ground id={`${id}/fill`} className="sheet" data-figma-compiled="" style={{ width: w, height: h, position: 'relative', overflow: 'hidden', background: '#fff' }}>
    <Picture id={`${id}/photo`} zone={zone} initialSrc={photo?.src} slot focus={crop?.focus}
      initialScale={crop?.initialScale} initialRotate={crop?.rotate} initialCrop={layout.frame.crop}
      style={{ position: 'absolute', inset: 0 }} />
    <FigmaLayers layout={drawn} slots={slots} nudges={NUDGE} />
  </Ground>;
}
